from pathlib import Path
import xml.etree.ElementTree as E
s=E.fromstring('<article>'+Path('source_article.xml').read_text()+'</article>')
p=E.fromstring('<article>'+Path('proposed_article.xml').read_text()+'</article>')
def tx(x):return ' '.join(''.join(x.itertext()).split())
for a,b in zip(s.findall('p'),p.findall('p')):print('SOURCE:',tx(a),'\\nPROPOSITION:',tx(b))
rows1=s.findall('table')[0].findall('./tbody/tr')
rows2=p.findall('table')[0].findall('./tbody/tr')
for i in range(1,88):
 a,b=rows1[i],rows2[i]
 print('\\nI',i,tx(a[0]))
 if tx(a[1])"'!=tx(b[1]):print('"'S:',tx(a[1]));print('P:',tx(b[1]))
 else:print('S=P:',tx(a[1]))
PY"

